# -*- coding: utf-8 -*-
# (speaker, spanish, korean); speaker None => stage direction, "#" => scene heading (neither is a turn)
L, K, Y, N, AN = "Lucas", "Min-seo", "Yu-na", "Nuria", "Andrés"
D = [
("#", "Escena 1 · 8:10 · Metro de Seúl, línea 2, rumbo a Seongsu", "장면 1 · 오전 8시 10분 · 서울 지하철 2호선, 성수 방면"),
(None, "Miércoles 1 de abril. Un vagón lleno pero silencioso. Casi todos miran el móvil. Yu-na le enseña a Lucas una tarjeta de transporte con un dibujo de un gato.", "4월 1일 수요일. 꽉 찼지만 조용한 객차. 거의 모두가 휴대폰을 보고 있다. 유나가 루카스에게 고양이 그림이 있는 교통카드를 보여 준다."),
(Y, "Esta es para ti. Se llama T-money. La pasas al entrar y al salir, y ya está. Le he puesto treinta mil wones.", "이건 루카스 거예요. 티머니라고 해요. 탈 때랑 내릴 때 찍기만 하면 돼요. 3만 원 충전해 놨어요."),
(L, "¿Con un gato?", "고양이가 그려진 걸로요?"),
(Y, "Era la única que quedaba en la tienda. El gato es muy profesional, te lo prometo.", "편의점에 그것밖에 안 남았었어요. 고양이도 아주 프로다워요, 진짜로."),
(L, "Como el árbol de Marc. Por cierto, he probado el desayuno coreano. Arroz, sopa de algas y kimchi a las siete de la mañana.", "마르크의 나무처럼요. 그건 그렇고, 한식 조식을 먹어 봤어요. 아침 7시에 밥, 미역국, 김치."),
(Y, "¿Y qué tal?", "어땠어요?"),
(L, "Me he despertado como si hubiera dormido diez horas. No sé si ha sido la sopa o el miedo a la presentación.", "열 시간은 잔 것처럼 깼어요. 국 때문인지 발표가 무서워서인지는 모르겠지만요."),
(Y, "Seguramente la sopa. En Corea se toma sopa de algas el día del cumpleaños. Da fuerzas.", "아마 국 때문일 거예요. 한국에선 생일에 미역국을 먹어요. 힘이 나거든요."),
(L, "¿Y la oficina de Seorin está en Gangnam, con el showroom?", "서린 사무실은 쇼룸이랑 같이 강남에 있어요?"),
(Y, "No. El showroom está en Gangnam porque allí están los clientes. La oficina está en Seongsu, en una antigua fábrica de zapatos. La daepyo-nim dice que las ideas se tienen mejor donde antes se fabricaba algo.", "아니요. 쇼룸은 고객이 거기 있으니까 강남에 있어요. 사무실은 성수동의 옛 구두 공장에 있어요. 대표님은 예전에 뭔가를 만들던 곳에서 아이디어가 더 잘 나온대요."),
(L, "Eso le gustaría a Pepe, nuestro jefe de planta.", "그 말은 저희 공장장 페페가 좋아하겠네요."),
(Y, "¿Pepe es el de los rodillos? La daepyo-nim nos enseñó una foto suya en Riad, con casco y bigote.", "페페가 롤러 그분이에요? 대표님이 리야드에서 안전모 쓰고 콧수염 난 사진을 보여 줬어요."),
(L, "Ese es. Ahora está allí, enseñando a colocar baldosas a cincuenta grados.", "그분 맞아요. 지금 거기서 50도에서 타일 까는 법을 가르치고 있어요."),
(Y, "¡Qué arte! Así decía mi compañera de piso en Valencia, que era de Sevilla.", "'케 아르테!' 발렌시아에서 같이 살던 세비야 출신 친구가 그렇게 말했어요."),
(L, "Pues Pepe diría «xe, quina calor». Cada uno con su acento.", "페페라면 '셰, 키나 칼로르(아이고, 덥다)'라고 하겠죠. 다들 자기 억양이 있으니까요."),

("#", "Escena 2 · 9:00 · Oficina de Seorin, sala de reuniones", "장면 2 · 오전 9시 · 서린 사무실, 회의실"),
(None, "Ladrillo visto, vigas de hierro y una mesa larga cubierta de muestras. En la pared, una foto antigua: obreros cosiendo zapatos en ese mismo lugar en los años setenta. Kim Min-seo ya está allí, con un café y una lista impresa.", "드러난 벽돌, 철제 들보, 샘플로 덮인 긴 탁자. 벽에는 70년대에 바로 이 자리에서 구두를 꿰매던 노동자들의 옛 사진이 걸려 있다. 김민서는 이미 커피와 출력한 목록을 들고 와 있다."),
(K, "Buenos días, señor Ferrer. ¿Ha descansado?", "좋은 아침이에요, 페레르 씨. 좀 쉬셨어요?"),
(L, "Sí, gracias. Y he desayunado sopa de algas, así que estoy preparado para todo.", "네, 감사합니다. 미역국까지 먹었으니 뭐든 준비됐어요."),
(K, "(sonríe) Entonces empezamos. He preparado una lista de las preguntas que harán los arquitectos de Hanul. Son diecisiete.", "(미소 지으며) 그럼 시작하죠. 한울 건축가들이 할 질문 목록을 준비했어요. 열일곱 개예요."),
(L, "¿Diecisiete? ¿Cómo sabe lo que van a preguntar?", "열일곱 개요? 무슨 질문을 할지 어떻게 아세요?"),
(K, "Llevo nueve años presentando a constructoras. Al principio me equivocaba en la mitad. Ahora, en dos o tres.", "건설사 상대로 9년째 발표하고 있어요. 처음엔 절반은 틀렸죠. 지금은 두세 개 정도요."),
(Y, "La pregunta número uno siempre es la misma.", "1번 질문은 항상 똑같아요."),
(K, "La calefacción por el suelo. El ondol.", "바닥 난방이요. 온돌."),
(L, "¿El ondol?", "온돌이요?"),
(K, "En casi todos los apartamentos coreanos, el calor sale del suelo. Los tubos de agua caliente van bajo el mortero, y encima, la baldosa. En invierno el suelo está tibio día y noche.", "한국 아파트는 거의 다 바닥에서 열이 나와요. 온수관이 모르타르 아래로 지나가고, 그 위에 타일을 깔죠. 겨울엔 바닥이 밤낮으로 따뜻해요."),
(L, "Entonces la baldosa se calienta y se enfría todos los días. Dilatación.", "그럼 타일이 매일 데워졌다 식었다 하겠네요. 팽창이요."),
(K, "Exacto. Hace tres años, un proveedor chino tuvo grietas en un complejo entero. Desde entonces, es lo primero que preguntan.", "맞아요. 3년 전에 한 중국 업체 제품이 단지 하나 전체에서 갈라졌어요. 그 뒤로 제일 먼저 묻는 게 그거예요."),
(L, "(abre el portátil) Entonces tengo una buena respuesta. En diciembre hicimos en Riad una prueba de choque térmico: la superficie a cincuenta grados, después agua fría, tres ciclos. Pasaron las ocho piezas.", "(노트북을 열며) 그럼 좋은 답이 있어요. 12월에 리야드에서 열충격 시험을 했어요. 표면을 50도로 올렸다가 찬물을 붓고, 세 번 반복. 여덟 장 모두 통과했어요."),
(K, "¿Tiene el informe?", "보고서 있으세요?"),
(L, "Firmado por la inspectora saudí. Y una lección que aprendimos allí: el problema casi nunca es la pieza, sino la junta perimetral y el adhesivo.", "사우디 검사관이 서명한 걸로요. 그리고 거기서 배운 게 있어요. 문제는 거의 늘 타일이 아니라 테두리 줄눈과 접착제라는 거요."),
(K, "Eso es exactamente lo que quieren oír. Póngalo en la diapositiva cuatro, no en la doce. Lo importante, al principio.", "그게 바로 그분들이 듣고 싶어 하는 말이에요. 12번 슬라이드 말고 4번에 넣으세요. 중요한 건 앞에."),
(L, "En España solemos dejar lo mejor para el final.", "스페인에선 보통 제일 좋은 걸 마지막에 남겨 두는데요."),
(K, "Aquí, si lo mejor está al final, el director Park ya habrá mirado el reloj tres veces.", "여기선 제일 좋은 게 마지막에 있으면 박 상무님이 이미 시계를 세 번은 보셨을 거예요."),
(Y, "Pregunta número dos: los pies descalzos.", "2번 질문은 맨발이에요."),
(L, "¿Descalzos?", "맨발이요?"),
(Y, "En Corea nadie entra en casa con zapatos. Se camina descalzo o con calcetines. El suelo se toca con los pies todo el día. Por eso miran la textura: que no sea fría, que no resbale con calcetines, que no se marque con la grasa del pie.", "한국에선 아무도 신발 신고 집에 안 들어가요. 맨발이나 양말로 다니죠. 하루 종일 발로 바닥을 만지는 거예요. 그래서 질감을 봐요. 차갑지 않은지, 양말 신고 미끄럽지 않은지, 발 기름 자국이 안 남는지."),
(L, "En España, en casa, mucha gente va con zapatillas. Nunca había pensado en el suelo como algo que se toca.", "스페인에선 집에서 실내화를 신는 사람이 많아요. 바닥을 만지는 거라고는 한 번도 생각해 본 적이 없네요."),
(K, "Aquí el suelo se toca, se mira desde muy cerca, y en muchas casas, se come y se duerme sobre él. Mientras que en Europa el suelo se pisa, en Corea se vive.", "여기선 바닥을 만지고, 아주 가까이서 보고, 많은 집에선 그 위에서 밥 먹고 잠도 자요. 유럽에선 바닥을 밟는다면, 한국에선 바닥에서 살아요."),
(L, "«En Corea el suelo se vive». ¿Puedo usar esa frase mañana?", "'한국에선 바닥에서 산다.' 그 말을 내일 써도 될까요?"),
(K, "Puede. Pero dígala usted, no yo. Si la dice un español, sorprende. Si la digo yo, es una obviedad.", "쓰세요. 대신 제가 아니라 페레르 씨가 말하세요. 스페인 사람이 말하면 놀랍고, 제가 말하면 당연한 소리니까요."),
(Y, "(mira la lista) Pregunta tres: el plazo. Cuatro: el tono entre lotes. Cinco: las piezas rotas. Seis...", "(목록을 보며) 3번은 납기. 4번은 로트 간 색조. 5번은 파손. 6번은…"),
(K, "Seis lo dejamos para la tarde. (a Lucas) ¿Le parece si repasamos ahora las tres primeras con sus números?", "6번은 오후에 하죠. (루카스에게) 지금은 첫 세 개를 숫자와 함께 정리하면 어떨까요?"),
(L, "Me parece perfecto. Y, señora Kim, ¿puedo hacerle yo una pregunta?", "좋습니다. 그리고 김 대표님, 제가 하나 여쭤봐도 될까요?"),
(K, "Por supuesto.", "물론이죠."),
(L, "¿Cuál es la pregunta diecisiete? La última.", "17번 질문은 뭔가요? 마지막 거요."),
(K, "(pausa) «¿Por qué deberíamos confiar en una fábrica que hace dos años solo vendía en España?»", "(잠시 멈추며) '2년 전만 해도 스페인에서만 팔던 공장을 왜 믿어야 합니까?'"),
(L, "(despacio) Esa es la buena.", "(천천히) 그게 진짜 질문이네요."),
(K, "Esa es la que hará el director Park. Piense la respuesta esta noche. Y no me la cuente: quiero oírla mañana, como él.", "그게 박 상무님이 할 질문이에요. 오늘 밤에 답을 생각해 보세요. 그리고 저한테 말하지 마세요. 내일 그분처럼 처음 들어 보고 싶어요."),

("#", "Escena 3 · 16:00 · Sala de reuniones — videollamada con Onda (9:00 en España)", "장면 3 · 오후 4시 · 회의실 — 온다와 화상 통화 (스페인 오전 9시)"),
(None, "En la pantalla grande aparece Nuria en su estudio, rodeada de muestras y con un café en la mano. Lucas ha colocado las cuatro piezas de ochenta por ciento sesenta en el suelo de la sala.", "큰 화면에 샘플에 둘러싸여 커피를 든 누리아가 작업실에서 나타난다. 루카스는 80×160 네 장을 회의실 바닥에 깔아 두었다."),
(N, "¡Buenos días desde Onda! Bueno, buenas tardes para vosotros. Hola, Lucas. Hola... ¿señora Kim?", "온다에서 좋은 아침! 아, 거긴 오후죠. 안녕, 루카스. 안녕하세요… 김 대표님?"),
(K, "Buenos días, señora Beltrán. Es un placer. Conozco su vestíbulo de Monterrey mejor que algunos de mis proyectos.", "좋은 아침이에요, 벨트란 씨. 반갑습니다. 몬테레이의 그 로비는 제 몇몇 프로젝트보다 더 잘 알아요."),
(N, "(se sonroja) Vaya. Gracias. Llámeme Nuria, por favor.", "(얼굴을 붉히며) 어머. 감사해요. 누리아라고 불러 주세요."),
(L, "Nuria, tenías razón con la veta. Mira la cámara: en la esquina de arriba, cada cuatro piezas, se repite el mismo dibujo.", "누리아, 결 무늬 얘기 맞았어요. 카메라 봐요. 위쪽 모서리에서 네 장마다 같은 무늬가 반복돼요."),
(N, "Lo sé. Lo vi en las fotos y no dormí. Para mañana, colócalas giradas: la primera normal, la segunda a ciento ochenta grados, la tercera normal, la cuarta girada. Así el ojo no encuentra el patrón.", "알아요. 사진 보고 잠을 못 잤어요. 내일은 돌려서 까세요. 첫째는 그대로, 둘째는 180도, 셋째는 그대로, 넷째는 돌려서. 그러면 눈이 패턴을 못 찾아요."),
(Y, "(se agacha y gira dos piezas) ¿Así?", "(쪼그려 앉아 두 장을 돌리며) 이렇게요?"),
(N, "¡Así! ¿Ves? Ya no se nota.", "그거예요! 봐요? 이제 티가 안 나죠."),
(K, "Para el showroom está bien. Pero en un salón de cuarenta metros, con dos mil seiscientos apartamentos, alguien lo verá.", "쇼룸용으로는 괜찮아요. 하지만 40제곱미터 거실이 2,600세대면 누군가는 볼 거예요."),
(N, "Por eso, para la producción, preparo un archivo con doce variaciones en lugar de cuatro. Con doce, para ver una repetición, tendría que poner su salón en un campo de fútbol.", "그래서 생산용으로는 네 가지 대신 열두 가지 변형 파일을 준비해요. 열두 가지면 반복을 보려면 거실을 축구장에 깔아야 할 거예요."),
(K, "(por primera vez se ríe abiertamente) Me gusta su manera de explicar las cosas, Nuria.", "(처음으로 소리 내어 웃으며) 설명하시는 방식이 마음에 들어요, 누리아."),
(N, "Gracias. Y otra cosa: la colección necesita un nombre para Corea. «Blanco San Pedro» es de Monterrey. ¿Qué tal «Luz del Han»? Por el río.", "감사해요. 그리고 하나 더요. 이 컬렉션에 한국용 이름이 필요해요. '블랑코 산페드로'는 몬테레이 거예요. '루스 델 한'은 어때요? 강 이름에서요."),
(K, "Es bonito. Pero aquí el río se llama Hangang, todo junto. Y Hanul ya tiene «Lumière», que significa luz. Dos luces son demasiada luz.", "예뻐요. 그런데 여기선 강을 '한강'이라고 붙여서 불러요. 그리고 한울은 이미 '뤼미에르', 즉 빛이라는 말이 있어요. 빛이 둘이면 너무 밝죠."),
(Y, "¿Y «Blanco Hangang»? Como «Blanco San Pedro», pero en Seúl. Que se vea que es de la misma familia.", "그럼 '블랑코 한강'은요? '블랑코 산페드로'처럼, 서울 버전으로요. 같은 집안이라는 게 보이게."),
(N, "¡Me encanta! Una familia de blancos con nombre de ciudad. Monterrey, Miami, Seúl...", "너무 좋아요! 도시 이름을 단 흰색 가족. 몬테레이, 마이애미, 서울…"),
(L, "Miami es «Blanco Biscayne», y el de Daniel, «Blanco Mercedes». La familia crece.", "마이애미는 '블랑코 비스케인', 다니엘 거는 '블랑코 메르세데스'. 가족이 늘어나네요."),
(K, "«Blanco Hangang». Lo propondremos mañana como nombre de trabajo. Si Hanul quiere otro, se cambia. Lo importante es que tenga historia.", "'블랑코 한강'. 내일 가제로 제안하죠. 한울이 다른 걸 원하면 바꾸면 돼요. 중요한 건 이야기가 있다는 거예요."),
(N, "Una pregunta, señora Kim: ¿en Corea gusta más el blanco frío o el cálido?", "하나 여쭤볼게요, 김 대표님. 한국에선 차가운 흰색이 좋아요, 따뜻한 흰색이 좋아요?"),
(K, "Cálido. Con el ondol, el suelo está tibio. Si el color es frío, el pie y el ojo no se ponen de acuerdo.", "따뜻한 쪽이요. 온돌 때문에 바닥이 따뜻하거든요. 색이 차가우면 발과 눈이 서로 말이 안 맞아요."),
(N, "¡Qué interesante! Entonces subo un poco el tono marfil en el semipulido.", "재밌네요! 그럼 반광 제품의 아이보리 톤을 조금 올릴게요."),
(Y, "¡Pero no mucho! Que si no, parece el suelo de una panadería.", "그래도 너무 많이는 말고요! 안 그러면 빵집 바닥 같아져요."),
(N, "(ríe) Entendido: marfil, pero no de panadería.", "(웃으며) 알겠어요. 아이보리, 하지만 빵집은 아니게."),
(L, "Nuria, ponlo así en la ficha técnica: «Marfil, no de panadería».", "누리아, 기술 사양서에 그렇게 적어 둬요. '아이보리, 빵집 아님.'"),
(N, "Os mando esta noche la imagen de la portada. Lucas, suerte mañana. Y cuidado con la diapositiva cuatro, que siempre se te desordena.", "오늘 밤에 표지 이미지 보낼게요. 루카스, 내일 행운을 빌어요. 그리고 4번 슬라이드 조심해요. 당신은 맨날 그거 순서가 엉키잖아요."),
(L, "¿Cómo sabes que la he cambiado a la cuatro?", "내가 4번으로 옮긴 건 어떻게 알았어요?"),
(N, "Porque la señora Kim tiene razón, y yo también lo habría hecho. ¡Adiós!", "김 대표님 말이 맞고, 나라도 그렇게 했을 테니까요. 안녕!"),

("#", "Escena 4 · 19:30 · Restaurante «Plaza Mayor», Hannam-dong", "장면 4 · 저녁 7시 30분 · 한남동, 레스토랑 '플라사 마요르'"),
(None, "Un local pequeño con azulejos de Talavera, una foto enmarcada de la Plaza Mayor de Salamanca de noche y olor a jamón. Detrás de la barra, un hombre de unos cincuenta y cinco años, bigote canoso y acento castellano, corta jamón a cuchillo.", "탈라베라 타일을 붙인 작은 가게. 밤의 살라망카 마요르 광장을 찍은 액자 사진이 걸려 있고 하몬 냄새가 난다. 바 뒤에서 하얗게 센 콧수염에 카스티야 억양을 쓰는 쉰다섯 살쯤의 남자가 칼로 하몬을 썰고 있다."),
(AN, "¡Min-seo! ¡Cuánto tiempo! ¿Y este caballero tan alto?", "민서 씨! 오랜만이에요! 이 키 큰 신사분은 누구시고요?"),
(K, "Andrés, te presento a Lucas Ferrer, de Cerámicas Albalat, de Onda. Lucas, Andrés es de Salamanca. Lleva quince años en Seúl.", "안드레스, 온다의 세라미카스 알발라트에서 오신 루카스 페레르 씨예요. 루카스, 안드레스는 살라망카 사람이에요. 서울에서 15년째 살고 있어요."),
(L, "Encantado, Andrés. ¿Quince años? ¿Y qué le trajo aquí?", "반가워요, 안드레스. 15년이요? 어쩌다 여기까지 오셨어요?"),
(AN, "Lo de siempre: una coreana que estudiaba en Salamanca. Me casé con ella y me vine detrás. Si me lo hubieran dicho a los veinte años, no me lo habría creído.", "늘 그렇듯이요. 살라망카에서 공부하던 한국 여자요. 결혼하고 따라왔죠. 스무 살 때 누가 그렇게 말했으면 안 믿었을 거예요."),
(K, "Su mujer y yo coincidimos en el máster. Así nos conocimos.", "그분 부인과 제가 석사 과정을 같이 했어요. 그렇게 알게 됐죠."),
(AN, "Y desde entonces, Min-seo viene aquí cada vez que echa de menos Salamanca. O sea, una vez al mes.", "그때부터 민서 씨는 살라망카가 그리울 때마다 여기 와요. 그러니까 한 달에 한 번."),
(K, "Dos, Andrés. No exageres a la baja.", "두 번이에요, 안드레스. 줄여서 말하지 마세요."),
(AN, "Os pongo jamón, unas patatas revolconas, como en casa, y un vino de Arribes. Lo demás, lo decido yo.", "하몬하고, 고향식 파타타스 레볼코나스, 그리고 아리베스 와인을 드릴게요. 나머지는 제가 정하고요."),
(L, "¿Arribes? Eso está en la frontera con Portugal, ¿no?", "아리베스요? 포르투갈 국경 쪽 아니에요?"),
(AN, "Junto al Duero. Mi pueblo está allí. Aquí no lo conoce nadie, pero los coreanos que lo prueban vuelven.", "두에로강 옆이요. 제 고향 마을이 거기 있어요. 여기선 아무도 모르지만 마셔 본 한국 사람들은 다시 와요."),
(K, "Como yo.", "저처럼요."),
(AN, "Como tú. ¿Y usted, Lucas, de dónde es?", "민서 씨처럼. 루카스 씨는 어디 출신이에요?"),
(L, "De Madrid, aunque ahora vivo en Onda, en Castellón. Mi abuela era de Burriana.", "마드리드요. 지금은 카스테욘의 온다에 살지만요. 할머니가 부리아나 분이셨어요."),
(AN, "¡Un madrileño en la tierra de las naranjas, y ahora en Seúl! Usted y yo somos de la misma tribu: la de los que se fueron.", "오렌지 땅에 사는 마드리드 사람이 이제 서울까지! 당신이랑 나는 같은 부족이에요. 떠나온 사람들 부족."),
(L, "(cuando Andrés se va) Señora Kim, ¿cómo llegó usted a Salamanca?", "(안드레스가 간 뒤) 김 대표님, 살라망카에는 어떻게 가시게 됐어요?"),
(K, "Con una beca, hace doce años. Tenía veintinueve años y trabajaba en una constructora grande, en el departamento de compras. Me acuerdo de que pedí la beca un viernes por la noche, casi sin pensarlo.", "12년 전에 장학금으로요. 스물아홉 살이었고 대형 건설사 구매부서에서 일하고 있었어요. 금요일 밤에 거의 생각도 안 하고 장학금을 신청했던 게 기억나요."),
(L, "¿Y por qué Salamanca?", "왜 살라망카였어요?"),
(K, "Porque mi padre tenía una pequeña tienda de azulejos en Busan. Recuerdo que en la trastienda había un catálogo español de los años noventa, con fotos de casas antiguas. Yo lo miraba de niña como si fuera un libro de cuentos.", "아버지가 부산에서 작은 타일 가게를 하셨거든요. 가게 안쪽 창고에 90년대 스페인 카탈로그가 하나 있었던 게 기억나요. 옛날 집 사진들이 실려 있었죠. 어릴 때 그걸 동화책처럼 봤어요."),
(L, "Así que todo empezó con un catálogo viejo. Como a mí. En mi primer mes en Onda encontré un catálogo de 2009 que lo cambió todo.", "그럼 모든 게 오래된 카탈로그에서 시작됐네요. 저처럼요. 저도 온다에서 첫 달에 모든 걸 바꿔 놓은 2009년 카탈로그를 찾았어요."),
(K, "¿De verdad? Entonces los catálogos viejos son peligrosos.", "정말요? 그럼 오래된 카탈로그는 위험하네요."),
(L, "Muy peligrosos. ¿Y qué recuerda de Salamanca?", "아주 위험하죠. 살라망카에서는 뭐가 기억나세요?"),
(K, "La Plaza Mayor a las once de la noche, llena de familias con niños pequeños. En Seúl, a esa hora, solo había oficinas encendidas. Y la rana.", "밤 11시의 마요르 광장이요. 어린아이들을 데리고 나온 가족들로 가득했어요. 서울은 그 시간에 불 켜진 사무실밖에 없었는데. 그리고 개구리요."),
(L, "¿La rana?", "개구리요?"),
(K, "En la fachada de la universidad hay una rana pequeña escondida entre las piedras, sobre una calavera. Dicen que el estudiante que la encuentra solo, sin ayuda, aprueba todos los exámenes.", "대학 정문 파사드에 돌 사이로 작은 개구리가 하나 숨어 있어요. 해골 위에요. 누구 도움 없이 혼자 그걸 찾는 학생은 시험에 다 붙는대요."),
(L, "¿Y usted la encontró sola?", "그래서 혼자 찾으셨어요?"),
(K, "Tardé tres semanas. Todos mis compañeros la habían encontrado ya, y yo me sentía como si hubiera suspendido el máster antes de empezarlo. Un día, sin buscarla, la vi.", "3주 걸렸어요. 동기들은 다 찾았는데 저는 석사 과정을 시작도 하기 전에 떨어진 기분이었죠. 어느 날, 찾지도 않았는데 보였어요."),
(L, "¿Y aprobó todo?", "그래서 다 붙으셨어요?"),
(K, "Todo. Y aprendí algo que ahora repito a mi equipo: en una fachada llena de detalles, lo importante es pequeño, y casi nadie lo ve a la primera.", "다요. 그리고 지금 제 팀에게 늘 하는 말을 배웠죠. 디테일로 가득한 파사드에서 중요한 건 작고, 처음엔 거의 아무도 못 본다는 것."),
(Y, "(a Lucas) Nos lo dice cada vez que revisamos una caja. «Buscad la rana».", "(루카스에게) 상자를 검수할 때마다 그 말을 해요. '개구리를 찾아라.'"),
(L, "«Buscad la rana». Mañana, en vuestro showroom, voy a buscar la rana del director Park.", "'개구리를 찾아라.' 내일 쇼룸에서 박 상무님의 개구리를 찾아볼게요."),
(AN, "(vuelve con los platos) ¿Ya os ha contado lo de la rana? Eso es que le caes bien. A mí me lo contó al quinto año.", "(접시를 들고 돌아오며) 벌써 개구리 얘기 했어요? 그럼 당신이 마음에 든다는 거예요. 저한텐 5년째에 해 줬다고요."),
(K, "Andrés, el jamón.", "안드레스, 하몬이요."),
(AN, "Ya voy, ya voy. (a Lucas) Cuidado con ella. Es la persona más exigente de Seúl. Y la más leal.", "가요, 가요. (루카스에게) 이분 조심해요. 서울에서 제일 깐깐한 사람이에요. 그리고 제일 의리 있는 사람이고요."),
(L, "Ya me he dado cuenta. De las dos cosas.", "벌써 알았어요. 둘 다요."),
(K, "(cambia de tema) ¿Y su padre, el de usted? ¿Qué piensa de que viaje tanto?", "(화제를 바꾸며) 페레르 씨 아버님은요? 이렇게 출장을 많이 다니는 걸 어떻게 생각하세요?"),
(L, "Mi padre murió hace seis años. Ojalá hubiera visto lo de este año. Era profesor de Historia en un instituto de Madrid; le habría encantado oír hablar de Riad y de Seúl.", "아버지는 6년 전에 돌아가셨어요. 올해 일을 보셨으면 좋았을 텐데요. 마드리드의 고등학교 역사 선생님이셨어요. 리야드랑 서울 얘기를 들으면 정말 좋아하셨을 거예요."),
(K, "Lo siento mucho. El mío vive todavía, en Busan. Tiene setenta y ocho años. Cuando le dije que iba a cenar con un español que vende azulejos, me pidió una foto del catálogo.", "정말 유감이에요. 제 아버지는 아직 부산에 살아 계세요. 일흔여덟이세요. 타일 파는 스페인 사람이랑 저녁 먹는다고 했더니 카탈로그 사진을 보내 달래요."),
(L, "Mañana, después de la presentación, se la hacemos juntos. Con la rana incluida.", "내일 발표 끝나고 같이 찍어 드려요. 개구리까지 넣어서요."),
(K, "Trato hecho. Y una cosa antes de que Andrés traiga más comida.", "약속이에요. 그리고 안드레스가 음식을 더 가져오기 전에 하나만요."),
(L, "Dígame.", "말씀하세요."),
(K, "Mañana viene el director Park. Escuche bien: odia la palabra «quizás». Si no sabe algo, diga «no lo sé, se lo confirmo mañana». Pero nunca «quizás».", "내일 박 상무님이 오세요. 잘 들으세요. 그분은 '아마도'라는 말을 싫어해요. 모르는 게 있으면 '모르겠습니다, 내일 확인해 드리겠습니다'라고 하세요. 하지만 절대 '아마도'는 안 돼요."),
(Y, "Y tampoco «a lo mejor». Ni «igual». Ni «ya veremos».", "'아마'도 안 되고요. '어쩌면'도. '두고 보죠'도요."),
(L, "Entonces mañana voy a hablar como un notario.", "그럼 내일은 공증인처럼 말해야겠네요."),
(K, "Como un notario no. Como alguien que sabe lo que puede cumplir. Es distinto.", "공증인처럼은 아니고요. 자기가 지킬 수 있는 게 뭔지 아는 사람처럼요. 그건 달라요."),
(L, "Lo que puedo cumplir. Eso me lo enseñó un cliente en Riad. Me dijo que fui el único que le había dicho que no.", "지킬 수 있는 것. 리야드의 한 고객이 가르쳐 준 거예요. 자기한테 '아니요'라고 한 사람은 제가 유일했다고 하더군요."),
(K, "Entonces el director Park y su cliente de Riad se entenderían muy bien.", "그럼 박 상무님과 그 리야드 고객은 아주 잘 통하겠네요."),
(AN, "(trae una bandeja) ¡Y ahora, el postre! Bollo maimón, como en Salamanca.", "(쟁반을 들고 오며) 자, 이제 디저트! 살라망카식 보요 마이몬이에요."),
(Y, "¡Andrés, que mañana trabajamos!", "안드레스, 우리 내일 일해야 해요!"),
(AN, "Mañana trabajáis. Hoy, Salamanca.", "일은 내일 하고, 오늘은 살라망카예요."),
]

PRE = [
("text", "장면 미리보기", "대화문을 읽기 전에 줄거리를 확인하고, 아래 질문의 답을 찾으며 읽어 보세요.", [
 "4월 1일 수요일. 유나와 지하철 2호선을 타고 옛 구두 공장을 고친 성수동 서린 사무실로 간다. 김민서는 한울 건축가들이 할 질문 열일곱 개를 미리 준비해 두었다. 1번은 온돌, 2번은 맨발이다. 오후에는 온다의 누리아와 화상으로 반복되는 결 무늬를 해결하고, 한국용 컬렉션 이름을 정한다. 저녁에는 한남동의 스페인 식당 '플라사 마요르'에서 살라망카 출신 주인 안드레스를 만나고, 김민서의 이야기를 듣는다. 부산의 타일 가게, 살라망카의 개구리, 그리고 박 상무가 싫어하는 단어.",
 "듣기 질문 ① 한국 건축가들의 1번과 2번 질문은 무엇이고, 왜 중요한가? 루카스는 1번 질문에 어떤 근거로 답하려 하는가?",
 "듣기 질문 ② 누리아는 반복되는 결 무늬를 쇼룸과 생산에서 각각 어떻게 해결하는가? 새 컬렉션 이름은 어떻게 정해지는가?",
 "듣기 질문 ③ 김민서가 살라망카에 간 계기와 '개구리' 이야기의 교훈은 무엇인가? 박 상무 앞에서 절대 쓰면 안 되는 말은?",
]),
]

